notion-help.stdout:
{
  "ok": true,
  "data": {
    "usage": "Usage:\n  outrank-cli products integrations notion databases <product-id> <integration-id>\n  outrank-cli products integrations notion schema <product-id> <integration-id> <database-id>"
  },
  "agent_guidance": "Use `databases` after Notion OAuth completes to list accessible Notion databases, then use `schema` to inspect one database before PATCHing the saved integration row with name, database_id, and fields."
}

webflow-help.stdout:
{
  "ok": true,
  "data": {
    "usage": "Usage:\n  outrank-cli products integrations webflow sites --json <object>\n  outrank-cli products integrations webflow collections --json <object>\n  outrank-cli products integrations webflow fields --json <object>\n  outrank-cli products integrations webflow items --json <object>"
  },
  "agent_guidance": "Use `sites` first to validate a Webflow token and list accessible sites, then `collections`, `fields`, and `items` to build the exact create or update payload for the chosen CMS collection."
}

framer-help.stdout:
{
  "ok": true,
  "data": {
    "usage": "Usage:\n  outrank-cli products integrations framer collections --json <object>\n  outrank-cli products integrations framer fields --json <object>"
  },
  "agent_guidance": "Use `collections` first with the Framer project URL and Server API key. Then use `fields` for one chosen collection if you want `collection_setup_mode: \"existing\"` instead of auto-creating a new collection."
}

